<script>
  // Fake track data
  const track = {
    title: "Sacrifice",
    artist: "Mariah the Scientist — HEARTS SOLD SEPARATELY",
    duration: 79, // seconds (1:19)
    art: "__PLACEHOLDER_ASSETS_BASE_DIR__/017.jpg"
  };

  // State
  let isPlaying = false;
  let currentTime = 0;
  let volume = 0.7;
  let raf = null;

  // Elements
  const overlay = document.getElementById('overlay');
  const btnOpen = document.querySelector('.btn-open');
  const miniArea = document.getElementById('miniPlayerArea');

  const topPlayIcon = document.getElementById('topPlayIcon');
  const ovPlayIcon  = document.getElementById('ovPlayIcon');

  const miniProg = document.querySelector('#miniProgress span');
  const progress = document.querySelector('#progress span');
  const curTimeEl = document.getElementById('curTime');
  const negTimeEl = document.getElementById('negTime');

  const topVol = document.getElementById('topVol');
  const ovVol  = document.getElementById('ovVol');

  // Utility
  function fmtTime(sec){
    sec = Math.max(0, Math.floor(sec));
    const m = Math.floor(sec/60);
    const s = String(sec%60).padStart(2,'0');
    return `${m}:${s}`;
  }
  function updateTimeUI(){
    const pct = (currentTime/track.duration)*100;
    miniProg.style.width = pct + '%';
    progress.style.width = pct + '%';
    curTimeEl.textContent = fmtTime(currentTime);
    const remain = Math.max(0, track.duration-currentTime);
    negTimeEl.textContent = '-' + fmtTime(remain);
  }
  function playLoop(){
    cancelAnimationFrame(raf);
    const tick = (ts)=>{
      if(!isPlaying){ return; }
      currentTime += 0.016;
      if(currentTime >= track.duration){ currentTime = track.duration; isPlaying=false; setPlayIcons(); }
      updateTimeUI();
      if(isPlaying) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
  }
  function setPlayIcons(){
    topPlayIcon.src = isPlaying ? "__PLACEHOLDER_ASSETS_BASE_DIR__/008.svg" : "__PLACEHOLDER_ASSETS_BASE_DIR__/011.svg";
    ovPlayIcon.src  = isPlaying ? "__PLACEHOLDER_ASSETS_BASE_DIR__/008.svg" : "__PLACEHOLDER_ASSETS_BASE_DIR__/011.svg";
  }

  function togglePlay(){
    isPlaying = !isPlaying;
    setPlayIcons();
    if(isPlaying){ playLoop(); }
  }
  function seekTo(pct){
    currentTime = Math.max(0, Math.min(track.duration, pct*track.duration));
    updateTimeUI();
  }

  // Bindings
  document.querySelectorAll('.btn-play, .btn-play-overlay').forEach(el=>el.addEventListener('click', togglePlay));
  document.querySelectorAll('.btn-next').forEach(el=>el.addEventListener('click', ()=>{
    currentTime = 0; updateTimeUI();
  }));
  document.querySelectorAll('.btn-prev').forEach(el=>el.addEventListener('click', ()=>{
    currentTime = 0; updateTimeUI();
  }));
  document.querySelectorAll('.btn-repeat').forEach(el=>el.addEventListener('click', (e)=>{
    e.currentTarget.classList.toggle('active');
  }));
  document.querySelectorAll('.btn-shuffle').forEach(el=>el.addEventListener('click', (e)=>{
    e.currentTarget.classList.toggle('active');
  }));

  // Mini progress seek
  document.getElementById('miniProgress').addEventListener('click', (e)=>{
    const rect = e.currentTarget.getBoundingClientRect();
    const pct = (e.clientX - rect.left) / rect.width;
    seekTo(pct);
  });
  // Overlay progress seek
  document.getElementById('progress').addEventListener('click', (e)=>{
    const rect = e.currentTarget.getBoundingClientRect();
    const pct = (e.clientX - rect.left) / rect.width;
    seekTo(pct);
  });

  // Open/close overlay
  [btnOpen, miniArea].forEach(el => el && el.addEventListener('click', ()=> overlay.classList.add('show')));
  document.querySelector('.btn-close').addEventListener('click', ()=> overlay.classList.remove('show'));

  // Volume sync
  function setVolume(v){
    volume = v;
    topVol.value = v;
    ovVol.value = v;
  }
  topVol.addEventListener('input', e=> setVolume(+e.target.value));
  ovVol.addEventListener('input', e=> setVolume(+e.target.value));
  setVolume(volume);

  // Init text
  document.getElementById('miniTitle').textContent = track.title;
  document.getElementById('ovTitle').textContent = track.title;
  document.getElementById('miniArtist').textContent = track.artist;
  document.getElementById('ovArtist').textContent = track.artist;
  updateTimeUI();

  // Allow clicking anywhere not otherwise interactive inside mini card to open overlay
  miniArea.addEventListener('click', ()=> overlay.classList.add('show'));
</script>
</body>
</html>
